/**
 * Pure rule for when a workspace is read-only because billing is not in good
 * standing. Callers that refuse a write throw `WorkspaceLockedError`; reads
 * and billing itself never consult this.
 */
import { toIsoTimestamp, type OrgId } from "@/types/common";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace is read-only (${reason})`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Lock decision for a subscription row at `now`.
 *
 * No row and `active` are writable. `past_due` is locked immediately.
 * `trialing` locks at the period end. `canceled` locks when `cancelAt` is
 * reached, and a canceled row with no cancellation date is locked now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null || subscription.status === "active") return null;
  if (subscription.status === "past_due") return "past_due";

  const nowIso = toIsoTimestamp(now);

  if (subscription.status === "trialing") {
    return subscription.currentPeriodEnd <= nowIso ? "trial_ended" : null;
  }

  if (subscription.cancelAt === null || subscription.cancelAt <= nowIso) {
    return "canceled";
  }

  return null;
}

